function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MyCalendarTwo' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with MyCalendarTwo and no arguments.';
  if (operations.length - 1 > 1000) return 'At most 1000 calls to book.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'book') return 'Only book can follow the constructor.';
    const call = args[i];
    if (!Array.isArray(call) || call.length !== 2 || !call.every(Number.isInteger)) return 'book takes two whole numbers.';
    const [startTime, endTime] = call;
    if (startTime < 0 || endTime > 1000000000 || startTime >= endTime) return 'book needs 0 <= startTime < endTime <= 10^9.';
  }
  return null;
}

