class MyCalendarTwo {
  constructor() {
    this.events = [];
  }
  book(startTime, endTime) {
    // Coverage only rises at a start, so the busiest moment of [startTime, endTime) is startTime or a later start inside it.
    const moments = [startTime, ...this.events.map(([s]) => s).filter(s => s > startTime && s < endTime)];
    for (const x of moments) {
      let cover = 0;
      for (const [s, e] of this.events) if (s <= x && x < e) cover++;
      if (cover >= 2) return false;
    }
    this.events.push([startTime, endTime]);
    return true;
  }
}

