function generate(rand, size) {
  const operations = ['MyCalendarTwo'];
  const args = [[]];
  const LIMIT = 1000000000;
  const made = [];
  if (size === 'large') {
    for (let i = 0; i < 499; i++) {
      const length = 1 + Math.floor(rand() * (rand() < 0.05 ? LIMIT : 10000000));
      const start = Math.floor(rand() * (LIMIT - length + 1));
      operations.push('book');
      args.push([start, start + length]);
    }
    return [operations, args];
  }
  const calls = 1 + Math.floor(rand() * 12);
  const limit = rand() < 0.15 ? LIMIT : 4 + Math.floor(rand() * 20);
  for (let i = 0; i < calls; i++) {
    let pair;
    if (made.length > 0 && rand() < 0.2) {
      pair = made[Math.floor(rand() * made.length)];
    } else {
      let a = Math.floor(rand() * (limit + 1));
      let b = Math.floor(rand() * (limit + 1));
      while (a === b) b = Math.floor(rand() * (limit + 1));
      pair = [Math.min(a, b), Math.max(a, b)];
    }
    made.push(pair);
    operations.push('book');
    args.push([pair[0], pair[1]]);
  }
  return [operations, args];
}
